import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Calendar, Clock, Send, Trash2, Key, Plus, Check, X } from 'lucide-react';
import './App.css';

function App() {
  // Animation variants
  const fadeIn = {
    initial: { opacity: 0, y: 20 },
    animate: { opacity: 1, y: 0 },
    exit: { opacity: 0, y: -20 }
  };
  const [apiKey, setApiKey] = useState('');
  const [savedKey, setSavedKey] = useState('');
  const [posts, setPosts] = useState([]);
  const [newPost, setNewPost] = useState({ content: '', platform: 'twitter', scheduledDate: '' });
  const [templates, setTemplates] = useState([
    { id: 1, name: 'Product Launch', content: 'Exciting news! 🎉 We\'re launching [Product Name]! Stay tuned for more details. #NewLaunch #Business' },
    { id: 2, name: 'Special Offer', content: '🔥 Special offer alert! Get [X]% off on all our products today only! Use code: [CODE] #SpecialOffer #Deal' },
    { id: 3, name: 'Business Update', content: 'We\'re excited to announce that we\'re now [Update]! Thank you for being part of our journey! #BusinessGrowth' }
  ]);

  useEffect(() => {
    const savedApiKey = localStorage.getItem('openai_api_key');
    if (savedApiKey) {
      setSavedKey(savedApiKey);
    }
    const savedPosts = localStorage.getItem('scheduled_posts');
    if (savedPosts) {
      setPosts(JSON.parse(savedPosts));
    }
  }, []);

  const handleSaveApiKey = () => {
    localStorage.setItem('openai_api_key', apiKey);
    setSavedKey(apiKey);
    setApiKey('');
  };

  const handleSchedulePost = () => {
    const post = {
      id: Date.now(),
      ...newPost,
      status: 'scheduled'
    };
    const updatedPosts = [...posts, post];
    setPosts(updatedPosts);
    localStorage.setItem('scheduled_posts', JSON.stringify(updatedPosts));
    setNewPost({ content: '', platform: 'twitter', scheduledDate: '' });
  };

  const handleUseTemplate = (template) => {
    setNewPost({
      ...newPost,
      content: template.content
    });
  };

  const handleDeletePost = (postId) => {
    const updatedPosts = posts.filter(post => post.id !== postId);
    setPosts(updatedPosts);
    localStorage.setItem('scheduled_posts', JSON.stringify(updatedPosts));
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100">
      <nav className="bg-white shadow-soft border-b border-gray-100">
        <div className="max-w-7xl mx-auto px-4 py-6">
          <motion.h1 
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-3xl font-display font-bold bg-gradient-to-r from-primary-600 to-accent-500 text-transparent bg-clip-text"
          >
            Local Business Marketing Assistant
          </motion.h1>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 py-12">
        {/* API Key Section */}
        <motion.section 
          variants={fadeIn}
          initial="initial"
          animate="animate"
          className="card mb-8"
        >
          <div className="flex items-center gap-3 mb-6">
            <Key className="w-6 h-6 text-primary-500" />
            <h2 className="text-2xl font-display">OpenAI API Configuration</h2>
          </div>
          {!savedKey ? (
            <div className="flex gap-4">
              <input
                type="password"
                value={apiKey}
                onChange={(e) => setApiKey(e.target.value)}
                placeholder="Enter your OpenAI API key"
                className="input flex-1"
              />
              <button
                onClick={handleSaveApiKey}
                className="btn btn-primary"
              >
                <Key className="w-4 h-4 mr-2" />
                Save API Key
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-4 p-4 bg-green-50 rounded-lg border border-green-200">
              <Check className="w-5 h-5 text-green-500" />
              <span className="text-green-700 font-medium">API Key configured successfully</span>
              <button
                onClick={() => {
                  localStorage.removeItem('openai_api_key');
                  setSavedKey('');
                }}
                className="ml-auto btn btn-secondary text-red-600 hover:bg-red-50 hover:border-red-200"
              >
                <X className="w-4 h-4 mr-2" />
                Remove Key
              </button>
            </div>
          )}
        </motion.section>

        {/* Post Scheduler Section */}
        <motion.section 
          variants={fadeIn}
          initial="initial"
          animate="animate"
          className="card mb-8"
        >
          <div className="flex items-center gap-3 mb-6">
            <Calendar className="w-6 h-6 text-primary-500" />
            <h2 className="text-2xl font-display">Post Scheduler</h2>
          </div>
          <div className="space-y-6">
            <div>
              <label htmlFor="post-content" className="label">Post Content</label>
              <textarea
                id="post-content"
                value={newPost.content}
                onChange={(e) => setNewPost({ ...newPost, content: e.target.value })}
                placeholder="Write your engaging post content here..."
                className="input h-32 resize-none"
              />
            </div>
            <div className="flex gap-4">
              <div className="flex-1">
                <label htmlFor="platform" className="label">Platform</label>
                <select
                  id="platform"
                  value={newPost.platform}
                  onChange={(e) => setNewPost({ ...newPost, platform: e.target.value })}
                  className="input"
                >
                  <option value="twitter">Twitter</option>
                  <option value="facebook">Facebook</option>
                  <option value="linkedin">LinkedIn</option>
                </select>
              </div>
              <div className="flex-1">
                <label htmlFor="schedule-date" className="label">Schedule Date</label>
                <input
                  id="schedule-date"
                  type="datetime-local"
                  value={newPost.scheduledDate}
                  onChange={(e) => setNewPost({ ...newPost, scheduledDate: e.target.value })}
                  className="input"
                />
              </div>
              <div className="flex items-end">
                <button
                  onClick={handleSchedulePost}
                  disabled={!newPost.content || !newPost.scheduledDate}
                  className="btn btn-primary h-[42px]"
                >
                  <Send className="w-4 h-4 mr-2" />
                  Schedule Post
                </button>
              </div>
            </div>
          </div>
        </motion.section>

        {/* Templates Section */}
        <motion.section 
          variants={fadeIn}
          initial="initial"
          animate="animate"
          className="card mb-8"
        >
          <div className="flex items-center gap-3 mb-6">
            <Plus className="w-6 h-6 text-primary-500" />
            <h2 className="text-2xl font-display">Marketing Templates</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {templates.map((template) => (
              <motion.div 
                key={template.id} 
                className="card-hover rounded-lg border border-gray-100 p-5"
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
              >
                <h3 className="text-lg font-semibold mb-3">{template.name}</h3>
                <p className="text-gray-600 mb-4 text-sm">{template.content}</p>
                <button
                  onClick={() => handleUseTemplate(template)}
                  className="btn btn-secondary w-full"
                >
                  Use Template
                </button>
              </motion.div>
            ))}
          </div>
        </motion.section>

        {/* Scheduled Posts Section */}
        <motion.section 
          variants={fadeIn}
          initial="initial"
          animate="animate"
          className="card"
        >
          <div className="flex items-center gap-3 mb-6">
            <Clock className="w-6 h-6 text-primary-500" />
            <h2 className="text-2xl font-display">Scheduled Posts</h2>
          </div>
          <div className="space-y-4">
            {posts.map((post) => (
              <motion.div 
                key={post.id} 
                className="card-hover rounded-lg border border-gray-100 p-5"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
              >
                <div className="flex justify-between items-start mb-3">
                  <span className="inline-flex items-center px-3 py-1 rounded-full text-sm font-medium bg-primary-50 text-primary-700 capitalize">
                    {post.platform}
                  </span>
                  <button
                    onClick={() => handleDeletePost(post.id)}
                    className="text-gray-400 hover:text-red-500 transition-colors"
                  >
                    <Trash2 className="w-5 h-5" />
                  </button>
                </div>
                <p className="text-gray-700 mb-3">{post.content}</p>
                <div className="flex items-center text-sm text-gray-500">
                  <Calendar className="w-4 h-4 mr-2" />
                  <time>{new Date(post.scheduledDate).toLocaleString()}</time>
                </div>
              </motion.div>
            ))}
            {posts.length === 0 && (
              <div className="text-center py-12">
                <Clock className="w-12 h-12 text-gray-300 mx-auto mb-4" />
                <p className="text-gray-500">No posts scheduled yet</p>
              </div>
            )}
          </div>
        </motion.section>
      </main>
    </div>
  );
}

export default App;
